import {
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  OnDestroy,
  effect,
  input,
  signal,
  viewChild
} from '@angular/core';

type ViewMode = 'tree' | 'code' | 'table';

interface TableColumn {
  key: string;
  label: string;
}

interface ArrayInfo {
  path: string;
  label: string;
  data: any[];
}

@Component({
  selector: 'app-json-viewer',
  standalone: true,
  imports: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './json-viewer.html',
  styleUrl: './json-viewer.scss'
})
export class JsonViewer implements AfterViewInit, OnDestroy {
  /** JSON data to display */
  data = input<any>(null);

  /** Currently active view mode */
  activeMode = signal<ViewMode>('tree');

  /** Available array paths found in the data for table view */
  arrayPaths = signal<ArrayInfo[]>([]);

  /** Currently selected array path for table view */
  selectedArrayPath = signal<string>('');

  /** Table columns for the selected array */
  tableColumns = signal<TableColumn[]>([]);

  /** Table rows for the selected array */
  tableRows = signal<any[]>([]);

  /** Expanded rows in table view (for nested arrays) */
  expandedRows = signal<Set<number>>(new Set());

  /** Reference to the vanilla-jsoneditor container */
  editorContainer = viewChild<ElementRef>('editorContainer');

  private editorInstance: any = null;

  constructor() {
    // React to data changes
    effect(() => {
      const d = this.data();
      if (d) {
        this.findArrays(d);
        this.updateEditor();
      }
    });

    // React to array path selection
    effect(() => {
      const path = this.selectedArrayPath();
      const d = this.data();
      if (path && d) {
        this.buildTable(d, path);
      }
    });
  }

  ngAfterViewInit(): void {
    this.initEditor();
  }

  ngOnDestroy(): void {
    if (this.editorInstance) {
      this.editorInstance.destroy();
    }
  }

  setMode(mode: ViewMode): void {
    this.activeMode.set(mode);
    if (mode === 'tree' || mode === 'code') {
      // Re-initialize editor with correct mode after view renders
      setTimeout(() => this.initEditor(), 0);
    }
  }

  selectArrayPath(path: string): void {
    this.selectedArrayPath.set(path);
  }

  toggleRowExpansion(index: number): void {
    this.expandedRows.update(set => {
      const newSet = new Set(set);
      if (newSet.has(index)) {
        newSet.delete(index);
      } else {
        newSet.add(index);
      }
      return newSet;
    });
  }

  isRowExpanded(index: number): boolean {
    return this.expandedRows().has(index);
  }

  copyToClipboard(): void {
    const d = this.data();
    if (d) {
      navigator.clipboard.writeText(JSON.stringify(d, null, 2));
    }
  }

  /** Get nested arrays within a table row for expansion */
  getNestedArrays(row: any): { key: string; data: any[] }[] {
    if (!row || typeof row !== 'object') return [];
    return Object.entries(row)
      .filter(([, v]) => Array.isArray(v) && v.length > 0)
      .map(([key, data]) => ({ key, data: data as any[] }));
  }

  /** Get columns for a nested array */
  getNestedColumns(data: any[]): TableColumn[] {
    if (!data.length) return [];
    const first = data[0];
    if (typeof first !== 'object' || first === null) {
      return [{ key: '_value', label: 'Value' }];
    }
    return Object.keys(first)
      .filter(k => !Array.isArray(first[k]) && typeof first[k] !== 'object')
      .map(k => ({ key: k, label: k }));
  }

  /** Get cell value formatted for display */
  getCellValue(row: any, key: string): string {
    if (key === '_value') return String(row);
    const val = row[key];
    if (val === null || val === undefined) return '';
    if (typeof val === 'object') return Array.isArray(val) ? `[${val.length}]` : '{...}';
    return String(val);
  }

  /** Check if a row has nested arrays */
  hasNestedArrays(row: any): boolean {
    if (!row || typeof row !== 'object') return false;
    return Object.values(row).some(v => Array.isArray(v) && v.length > 0);
  }

  private async initEditor(): Promise<void> {
    const container = this.editorContainer()?.nativeElement;
    if (!container) return;

    if (this.editorInstance) {
      this.editorInstance.destroy();
      this.editorInstance = null;
    }

    try {
      const vje = await import('vanilla-jsoneditor');
      const mode = this.activeMode();
      const EditorClass = vje.JSONEditor as any;

      this.editorInstance = new EditorClass({
        target: container,
        props: {
          content: { json: this.data() || {} },
          mode: mode === 'tree' ? 'tree' : 'text',
          readOnly: true,
          mainMenuBar: true,
          navigationBar: true
        }
      });
    } catch {
      // vanilla-jsoneditor not available — fallback to raw display
      container.innerHTML = `<pre style="padding:12px;overflow:auto;max-height:100%">${JSON.stringify(this.data(), null, 2)}</pre>`;
    }
  }

  private updateEditor(): void {
    if (this.editorInstance) {
      try {
        this.editorInstance.set({ json: this.data() || {} });
      } catch {
        // Ignore update errors
      }
    }
  }

  /** Recursively find all arrays in the data */
  private findArrays(obj: any, path: string = '', results: ArrayInfo[] = []): ArrayInfo[] {
    if (!obj || typeof obj !== 'object') return results;

    if (Array.isArray(obj) && obj.length > 0) {
      const label = path || 'root';
      results.push({ path: path || '$', label, data: obj });
    }

    if (!Array.isArray(obj)) {
      for (const [key, value] of Object.entries(obj)) {
        const newPath = path ? `${path}.${key}` : key;
        if (Array.isArray(value) && value.length > 0) {
          results.push({ path: newPath, label: `${key} (${value.length})`, data: value });
          // Also search inside array items for nested arrays
          if (typeof value[0] === 'object') {
            for (const [nestedKey, nestedValue] of Object.entries(value[0])) {
              if (Array.isArray(nestedValue)) {
                // Note the nested array but don't add it — it'll show in row expansion
              }
            }
          }
        } else if (typeof value === 'object' && value !== null) {
          this.findArrays(value, newPath, results);
        }
      }
    }

    this.arrayPaths.set(results);

    // Auto-select first array
    if (results.length > 0 && !this.selectedArrayPath()) {
      this.selectedArrayPath.set(results[0].path);
    }

    return results;
  }

  /** Build table data from a selected array path */
  private buildTable(data: any, path: string): void {
    const arrayData = this.getValueAtPath(data, path);
    if (!Array.isArray(arrayData) || arrayData.length === 0) {
      this.tableColumns.set([]);
      this.tableRows.set([]);
      return;
    }

    // Derive columns from the first element's scalar properties
    const first = arrayData[0];
    if (typeof first !== 'object' || first === null) {
      this.tableColumns.set([{ key: '_value', label: 'Value' }]);
      this.tableRows.set(arrayData);
      return;
    }

    const columns: TableColumn[] = Object.keys(first)
      .filter(k => !Array.isArray(first[k]) && (typeof first[k] !== 'object' || first[k] === null))
      .map(k => ({ key: k, label: k }));

    this.tableColumns.set(columns);
    this.tableRows.set(arrayData);
    this.expandedRows.set(new Set());
  }

  /** Navigate to a value at a dot-separated path */
  private getValueAtPath(obj: any, path: string): any {
    if (path === '$') return obj;
    return path.split('.').reduce((acc, key) => acc?.[key], obj);
  }
}
