import { Injectable, inject, signal } from '@angular/core';
import { MPageService } from '@clinicaloffice/mpage-developer';
import { ServiceDefinition, ExecutionResult } from '../models/service-definition.model';
import { ParameterLibraryService } from './parameter-library.service';

declare const XMLCclRequest: any;

const HISTORY_KEY = 'dwsv_execution_history';
const MAX_HISTORY = 50;

@Injectable({ providedIn: 'root' })
export class CclExecutorService {
  private mPage = inject(MPageService);
  private paramLibrary = inject(ParameterLibraryService);

  private _executing = signal(false);
  private _history = signal<ExecutionResult[]>([]);

  readonly executing = this._executing.asReadonly();
  readonly history = this._history.asReadonly();

  constructor() {
    this.loadHistory();
  }

  /**
   * Execute a CCL program with the given parameter values.
   * Uses XMLCclRequest when running inside PowerChart/DiscernReportViewer.
   */
  execute(service: ServiceDefinition, parameterValues: Record<string, string>): Promise<ExecutionResult> {
    this._executing.set(true);
    const startTime = Date.now();

    // Build the parameter string: ^value1^,^value2^,...
    const paramString = this.buildParameterString(service, parameterValues);

    const resultBase: Omit<ExecutionResult, 'durationMs' | 'success' | 'response' | 'errorMessage'> = {
      id: crypto.randomUUID(),
      serviceId: service.id,
      serviceName: service.displayName,
      parameterValues: { ...parameterValues },
      rawParameterString: paramString,
      timestamp: new Date()
    };

    return this.executeXmlCclRequest(service.programName, paramString)
      .then(response => {
        const result: ExecutionResult = {
          ...resultBase,
          durationMs: Date.now() - startTime,
          success: true,
          response
        };
        this.addToHistory(result);
        return result;
      })
      .catch(error => {
        const result: ExecutionResult = {
          ...resultBase,
          durationMs: Date.now() - startTime,
          success: false,
          errorMessage: error.message || String(error)
        };
        this.addToHistory(result);
        return result;
      })
      .finally(() => {
        this._executing.set(false);
      });
  }

  /** Build the ^param1^,^param2^ string from service definition and values */
  buildParameterString(service: ServiceDefinition, values: Record<string, string>): string {
    const sortedParams = [...service.parameters].sort((a, b) => a.position - b.position);

    return sortedParams.map(param => {
      const paramType = this.paramLibrary.getType(param.parameterTypeKey);
      const value = values[param.parameterTypeKey]
        ?? param.defaultValueOverride
        ?? paramType?.defaultValue
        ?? '';
      return `^${value}^`;
    }).join(',');
  }

  /** Clear execution history */
  clearHistory(): void {
    this._history.set([]);
    localStorage.removeItem(HISTORY_KEY);
  }

  private executeXmlCclRequest(programName: string, paramString: string): Promise<any> {
    return new Promise((resolve, reject) => {
      try {
        const info = new XMLCclRequest();
        info.onreadystatechange = function () {
          if (info.readyState === 4 && info.status === 200) {
            try {
              const text = info.responseText || '{}';
              // Clean up common CCL JSON issues (trailing commas)
              const cleaned = text.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');
              resolve(JSON.parse(cleaned));
            } catch (parseError: any) {
              // Return raw text if not valid JSON
              resolve({ _rawResponse: info.responseText });
            }
          } else if (info.readyState === 4) {
            reject(new Error(`CCL request failed with status ${info.status}: ${info.statusText || 'Unknown error'}`));
          }
        };
        info.open('GET', programName, true);
        info.send(paramString);
      } catch (error: any) {
        reject(new Error(`XMLCclRequest not available: ${error.message}. This tool must run inside PowerChart or DiscernReportViewer.`));
      }
    });
  }

  private addToHistory(result: ExecutionResult): void {
    this._history.update(history => {
      const updated = [result, ...history].slice(0, MAX_HISTORY);
      this.saveHistory(updated);
      return updated;
    });
  }

  private loadHistory(): void {
    try {
      const stored = localStorage.getItem(HISTORY_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        this._history.set(parsed.map((r: any) => ({ ...r, timestamp: new Date(r.timestamp) })));
      }
    } catch {
      // Ignore
    }
  }

  private saveHistory(history: ExecutionResult[]): void {
    try {
      localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(0, MAX_HISTORY)));
    } catch {
      // localStorage may be full
    }
  }
}
