import { ChangeDetectionStrategy, Component, computed, inject, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ServiceDefinition, ServiceParameter } from '../../models/service-definition.model';
import { ParameterType } from '../../models/parameter-library.model';
import { ParameterLibraryService } from '../../services/parameter-library.service';

interface ResolvedParameter {
  serviceParam: ServiceParameter;
  paramType: ParameterType;
  value: string;
}

@Component({
  selector: 'app-parameter-form',
  standalone: true,
  imports: [FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './parameter-form.html',
  styleUrl: './parameter-form.scss'
})
export class ParameterForm {
  private paramLibrary = inject(ParameterLibraryService);

  /** The service definition whose parameters to render */
  service = input.required<ServiceDefinition>();

  /** Emitted when the user clicks Execute */
  executeRequested = output<Record<string, string>>();

  /** Current parameter values keyed by parameterTypeKey */
  private _values = signal<Record<string, string>>({});

  /** Resolved parameters with their library types, sorted by position */
  readonly resolvedParams = computed(() => {
    const svc = this.service();
    if (!svc) return [];

    const sorted = [...svc.parameters].sort((a, b) => a.position - b.position);
    return sorted
      .map(sp => {
        const pt = this.paramLibrary.getType(sp.parameterTypeKey);
        if (!pt) return null;
        return {
          serviceParam: sp,
          paramType: pt,
          value: this._values()[sp.parameterTypeKey]
            ?? sp.defaultValueOverride
            ?? pt.defaultValue
            ?? ''
        } as ResolvedParameter;
      })
      .filter((p): p is ResolvedParameter => p !== null);
  });

  /** Only visible (non-hidden) parameters */
  readonly visibleParams = computed(() =>
    this.resolvedParams().filter(p => p.paramType.inputType !== 'hidden')
  );

  /** Update a parameter value */
  setValue(key: string, value: string): void {
    this._values.update(v => ({ ...v, [key]: value }));
  }

  /** Get the current value for a parameter */
  getValue(key: string): string {
    const resolved = this.resolvedParams().find(p => p.serviceParam.parameterTypeKey === key);
    return resolved?.value ?? '';
  }

  /** Submit the form */
  onExecute(): void {
    const values: Record<string, string> = {};
    for (const rp of this.resolvedParams()) {
      values[rp.serviceParam.parameterTypeKey] = rp.value;
    }
    this.executeRequested.emit(values);
  }

  /** Reset all values to defaults */
  resetDefaults(): void {
    this._values.set({});
  }
}
